import { useEffect, useState } from "react";
import axios from "axios";
const API_URL = "http://54.79.136.187:5001";
//import { API_URL } from "../config";

const MyBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [units, setUnits] = useState([]);
  const [filterStatus, setFilterStatus] = useState("all");
  const [sortBy, setSortBy] = useState("date");

  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showPayModal, setShowPayModal] = useState(false);
  
  const [showUpdateModal, setShowUpdateModal] = useState(false);

  /*const [paymentForm, setPaymentForm] = useState({
    name: "",
    cardNumber: "",
    expiry: "",
    cvv: ""
  });*/

  const [updateForm, setUpdateForm] = useState({
    unitId: "",
    startDate: "",
    endDate: "",
    pricePerDay: 0
  });

  const userInfo = JSON.parse(localStorage.getItem("userInfo"));
  const token = userInfo?.token;

  // ✅ FETCH BOOKINGS
  useEffect(() => {
    const fetchBookings = async () => {
      const { data } = await axios.get(
        `${API_URL}/api/bookings/my`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setBookings(data);
    };

    if (token) fetchBookings();
  }, [token]);

  // ✅ FETCH UNITS
  useEffect(() => {
    const fetchUnits = async () => {
      const { data } = await axios.get(`${API_URL}/api/units`);
      setUnits(data);
    };
    fetchUnits();
  }, []);

  // ✅ CALCULATE PRICE (UPDATE MODAL)
  const calculateUpdatedCost = () => {
    if (!updateForm.startDate || !updateForm.endDate) return 0;

    const start = new Date(updateForm.startDate);
    const end = new Date(updateForm.endDate);

    start.setHours(0, 0, 0, 0);
    end.setHours(0, 0, 0, 0);

    const diff = end - start;
    const days = Math.floor(diff / (1000 * 60 * 60 * 24)) + 1;

    return days > 0 ? days * updateForm.pricePerDay : 0;
  };

  // ✅ FILTER + SORT
  let filteredBookings =
    filterStatus === "all"
      ? bookings
      : bookings.filter((b) => b.status === filterStatus);

  filteredBookings = [...filteredBookings].sort((a, b) => {
    if (sortBy === "date") {
      return new Date(b.createdAt) - new Date(a.createdAt);
    }
    if (sortBy === "cost") {
      return b.totalCost - a.totalCost;
    }
    return 0;
  });

  return (
    <div style={{ padding: "30px" }}>
      <h2>My Bookings</h2>

      {/* ✅ FILTER */}
      <div style={{ marginBottom: "15px" }}>
        <label>Status: </label>
        <select onChange={(e) => setFilterStatus(e.target.value)}>
          <option value="all">All</option>
          <option value="pending">Pending</option>
          <option value="confirmed">Confirmed</option>
          <option value="cancelled">Cancelled</option>
        </select>

        <label style={{ marginLeft: "20px" }}>Sort by: </label>
        <select onChange={(e) => setSortBy(e.target.value)}>
          <option value="date">Date</option>
          <option value="cost">Total Cost</option>
        </select>
      </div>

      {/* ✅ TABLE */}
      <table style={table}>
        <thead style={thead}>
          <tr>
            <th style={th}>Unit</th>
            <th style={th}>Start Date</th>
            <th style={th}>End Date</th>
            <th style={th}>Status</th>
            <th style={th}>Total Cost</th>
          </tr>
        </thead>

        <tbody>
          {filteredBookings.map((b) => (
            <tr key={b._id}>
              <td style={td}>{b.unitId?.name}</td>
              <td style={td}>{new Date(b.startDate).toLocaleDateString()}</td>
              <td style={td}>{new Date(b.endDate).toLocaleDateString()}</td>

              <td style={td}>
                <span style={statusStyle(b.status)}>{b.status}</span>
              </td>

              <td style={td}>
                ${b.totalCost}

                {/* PAY */}
                {b.status === "pending" && (
                  <button style={payBtn} onClick={() => {
                    setSelectedBooking(b);
                    setShowPayModal(true);
                  }}>
                    Pay Now
                  </button>
                )}

                {/* UPDATE */}
                {b.status !== "cancelled" && (
                  <button style={updateBtn} onClick={() => {
                    setSelectedBooking(b);
                    setUpdateForm({
                      unitId: b.unitId._id,
                      startDate: b.startDate.split("T")[0],
                      endDate: b.endDate.split("T")[0],
                      pricePerDay: b.unitId.pricePerDay
                    });
                    setShowUpdateModal(true);
                  }}>
                    Update
                  </button>
                )}

                {/* CANCEL */}
                {b.status !== "cancelled" && (
                  <button style={cancelBtnRow} onClick={async () => {
                    if (!window.confirm("Cancel booking?")) return;

                    await axios.put(
                      `${API_URL}/api/bookings/cancel/${b._id}`,
                      {},
                      { headers: { Authorization: `Bearer ${token}` } }
                    );

                    window.location.reload();
                  }}>
                    Cancel
                  </button>
                )}

              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* ✅ UPDATE MODAL */}
      {showUpdateModal && (
        <div style={overlay}>
          <div style={modal}>
            <h3>Update Booking</h3>

            <label>Unit</label>
            <select
              value={updateForm.unitId}
              onChange={(e) => {
                const unit = units.find(u => u._id === e.target.value);
                setUpdateForm({
                  ...updateForm,
                  unitId: e.target.value,
                  pricePerDay: unit.pricePerDay
                });
              }}
              style={input}
            >
              {units.map(u => (
                <option key={u._id} value={u._id}>
                  {u.name} (${u.pricePerDay}/day)
                </option>
              ))}
            </select>

            <label>Start Date</label>
            <input
              type="date"
              value={updateForm.startDate}
              onChange={(e) =>
                setUpdateForm({ ...updateForm, startDate: e.target.value })
              }
              style={input}
            />

            <label>End Date</label>
            <input
              type="date"
              value={updateForm.endDate}
              onChange={(e) =>
                setUpdateForm({ ...updateForm, endDate: e.target.value })
              }
              style={input}
            />

            <p><strong>Updated Cost:</strong> ${calculateUpdatedCost()}</p>

            <button style={primaryBtn} onClick={async () => {
              await axios.put(
                `${API_URL}/api/bookings/update/${selectedBooking._id}`,
                updateForm,
                { headers: { Authorization: `Bearer ${token}` } }
              );
              window.location.reload();
            }}>
              Save Changes
            </button>

            <button style={cancelBtn} onClick={() => setShowUpdateModal(false)}>
              Close
            </button>
          </div>
        </div>
      )}

      
{/* ✅ PAY MODAL */}
{showPayModal && (
  <div style={overlay}>
    <div style={modal}>
      <h3>Payment</h3>

      <p>Enter payment details here</p>

      <button onClick={() => setShowPayModal(false)}>
        Close
      </button>
    </div>
  </div>
)}

    </div>
  );
};

